-- 0115_printing: price labels on 80 mm receipt printers (ADR-0226): the printers (a LAN printer the
-- api writes to, or a Windows PC's bridge with its key's sha-256) and the print jobs with their
-- ESC/POS bytes. New tables only (ADR-0206). Generated by drizzle-kit; added by hand: the REVOKEs
-- at the end (a station is disabled, never deleted; a job is kept with its outcome).
CREATE TABLE "print_jobs" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "print_jobs_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"station_id" bigint NOT NULL,
	"till_id" bigint,
	"payload" "bytea",
	"labels" integer NOT NULL,
	"status" text DEFAULT 'QUEUED' NOT NULL,
	"error" text,
	"created_by" bigint NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"picked_at" timestamp with time zone,
	"finished_at" timestamp with time zone,
	CONSTRAINT "print_jobs_status" CHECK ("print_jobs"."status" IN ('QUEUED', 'PRINTING', 'DONE', 'FAILED')),
	CONSTRAINT "print_jobs_labels" CHECK ("print_jobs"."labels" BETWEEN 1 AND 100),
	CONSTRAINT "print_jobs_error" CHECK (("print_jobs"."status" = 'FAILED') = ("print_jobs"."error" IS NOT NULL) AND ("print_jobs"."error" IS NULL OR char_length("print_jobs"."error") BETWEEN 1 AND 500)),
	CONSTRAINT "print_jobs_finished" CHECK (("print_jobs"."status" IN ('DONE', 'FAILED')) = ("print_jobs"."finished_at" IS NOT NULL))
);
--> statement-breakpoint
CREATE TABLE "print_stations" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "print_stations_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"name" text NOT NULL,
	"kind" text NOT NULL,
	"host" text,
	"port" integer,
	"key_hash" text,
	"printer_name" text,
	"width_dots" smallint DEFAULT 576 NOT NULL,
	"status" text DEFAULT 'ACTIVE' NOT NULL,
	"last_seen_at" timestamp with time zone,
	"created_by" bigint NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "print_stations_name" CHECK (char_length("print_stations"."name") BETWEEN 1 AND 80),
	CONSTRAINT "print_stations_kind" CHECK ("print_stations"."kind" IN ('BRIDGE', 'NETWORK')),
	CONSTRAINT "print_stations_status" CHECK ("print_stations"."status" IN ('ACTIVE', 'DISABLED')),
	CONSTRAINT "print_stations_width" CHECK ("print_stations"."width_dots" IN (576, 384)),
	CONSTRAINT "print_stations_network" CHECK ("print_stations"."kind" <> 'NETWORK' OR ("print_stations"."host" IS NOT NULL AND char_length("print_stations"."host") BETWEEN 1 AND 253 AND "print_stations"."port" BETWEEN 1 AND 65535)),
	CONSTRAINT "print_stations_bridge" CHECK ("print_stations"."kind" <> 'BRIDGE' OR "print_stations"."key_hash" IS NOT NULL),
	CONSTRAINT "print_stations_printer_name" CHECK ("print_stations"."printer_name" IS NULL OR char_length("print_stations"."printer_name") BETWEEN 1 AND 200)
);
